// Authored explanations remain distinct from generated AI and quoted publisher text.
const CONSULT_GUIDES={
 knee:{name:'Knee pain',match:/\bknee\b/i,source:{name:'MedlinePlus medical encyclopedia',url:'https://medlineplus.gov/ency/article/003187.htm',credentials:'Source updated by C. Benjamin Ma, MD, UCSF Professor and Chief of Sports Medicine and Shoulder Service. Reviewed November 7, 2024.'},overview:'Knee pain describes what you feel, but it does not tell us the cause. It can follow an injury or repeated strain, or develop gradually with a joint problem. That is why jumping straight to a condition such as gout can be misleading.',why:'The knee contains several structures that can become irritated or injured. Tendons attach muscle to bone; ligaments help hold the joint steady; cartilage cushions movement. Similar pain can come from different structures, so the story of how it started matters.',next:'A clinician can examine the knee and decide whether imaging or other tests would help. You can prepare by noting where it hurts, when it started, and whether it swells, locks or gives way.',urgent:'Seek medical advice if you cannot bear weight, have severe pain, a deformed or locked knee, or fever with redness, warmth or swelling. Pain after an accident or injury also needs assessment.',question:'Would it help to explain the possible causes, or how a clinician investigates knee pain?'},
 anxiety:{name:'Anxiety',match:/\banxi(?:ety|ous)\b/i,source:{name:'National Institute of Mental Health',url:'https://www.nimh.nih.gov/health/publications/generalized-anxiety-disorder-gad',credentials:'NIH research institute; public guidance on generalized anxiety disorder.'},overview:'Anxiety can affect your body as well as your thoughts. Worry may come with tense muscles, poor sleep, trouble concentrating or feeling worn out. These experiences are real, but they do not by themselves establish an anxiety disorder.',why:'Fatigue and sleep difficulties can accompany generalized anxiety disorder. Depression can occur alongside it, which is why those are useful related topics. That does not mean every physical symptom is caused by anxiety; a clinician also considers other explanations.',next:'When worry is difficult to control or disrupts daily life, a health professional can assess it. Treatment can include psychological therapy, medicines, or both. Cognitive behavioral therapy helps people examine patterns of thinking and behavior that keep anxiety going.',question:'Would you like to understand the physical symptoms, or what getting support can involve?'},
 fatigue:{name:'Fatigue',match:/\bfatigue|\btired|\bexhaust/i,source:{name:'MedlinePlus / National Institute on Aging',url:'https://medlineplus.gov/fatigue.html',credentials:'U.S. National Library of Medicine; summary attributed to the NIH National Institute on Aging.'},overview:'Fatigue means a lack of energy that can get in the way of everyday life. It is a symptom, not a single disease. Sleep, stress, medicines and physical or mental health conditions can all contribute, so a tiredness search cannot identify the cause on its own.',why:'The same feeling can arise in different ways. For example, a sleep problem can interrupt restorative sleep, while some medicines can leave you tired. Anemia, thyroid problems and depression are other possibilities a clinician may consider based on your history.',next:'If tiredness continues for several weeks, arrange a clinical review. Notes about your sleep, daily activity, medicines and when your energy drops can help the discussion. A clinician may use an examination and tests to narrow the possibilities.',question:'Would you like help preparing for an appointment, or understanding why fatigue can have different causes?'}
};
let guideTopic=null,consultBusy=false,consultEpoch=0,liveAvailable=false,useLive=false,consultDraft='';
const followupPrompts=['Explain that more simply','How is it investigated?','What should I ask my doctor?'];
function guideCitation(s){return `<details class="consult-sources"><summary>Source & credibility · ${esc(s.name)}</summary><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.name)}</a><p>${esc(s.credentials||s.publisher||'')}</p><p class="fine">Explanation written by Prognos from this source. It has not had independent clinical review.</p></details>`}
function guideIntent(q){return /medicine|medication|treatment|side effect/i.test(q)?'treatment':/symptom|signs/i.test(q)?'symptoms':/simpl|plain|understand|mean/i.test(q)?'simple':/why|cause|happen|physical/i.test(q)?'why':/test|diagnos|investigat|doctor|appointment|next|support|treat|help/i.test(q)?'next':'overview'}
function resolveGuide(q){const direct=Object.entries(CONSULT_GUIDES).find(([,g])=>g.match.test(q));if(direct)return direct[0];const n=normalizeQuery(q);const authored=DATA.conditions.find(c=>[c.name,names[c.id],c.id].some(t=>n.includes(fold(t))));if(authored)return authored.id;const explicit=educationalResults(q,{mode:'general',filters:false})[0];if(explicit&&(fold(explicit.name)===n||explicit.aliases.some(a=>fold(a)===n))){guideTopic=null;return null}return /^(why|how|what|explain|tell|can you)|\b(that|it|this|doctor|test|support)\b/i.test(q)?guideTopic:null}
function urgentQuestion(q){return /\b(can.?t breathe|cannot breathe|struggling to breathe|chest pressure|chest pain|face droop|new weakness|worst headache|overdose|kill myself|suicid|severe pain)\b/i.test(q)}
function localConsult(q){if(urgentQuestion(q))return '<p>These symptoms can need urgent help. Please contact emergency services now if they are happening, severe or sudden. This conversation cannot assess an emergency.</p><a class="primary" href="#emergency">Emergency numbers and help</a><p><a href="https://medlineplus.gov/ency/article/001927.htm" target="_blank" rel="noopener">Emergency warning signs · MedlinePlus</a></p>';
 const topic=resolveGuide(q),intent=guideIntent(q);if(topic){guideTopic=topic;const g=CONSULT_GUIDES[topic];if(g){let text=intent==='why'?g.why:(intent==='next'||intent==='treatment')?g.next:g.overview;return `<p class="reply-label">About ${esc(g.name.toLowerCase())}</p><p>${esc(text)}</p>${intent==='overview'?`<p>${esc(g.next)}</p>`:''}${g.urgent&&intent==='next'?`<p>${esc(g.urgent)}</p>`:''}${guideCitation(g.source)}<p class="consult-question">${esc(g.question)}</p>`}const c=DATA.conditions.find(c=>c.id===topic);if(intent==='treatment')return `<p>Here is how one example medicine class used for ${esc(names[c.id])} works. This does not establish whether it is suitable for you.</p>${c.treatments.map(t=>`<h3>${esc(t.name)}</h3><p>${esc(t.action)}</p><p>Side effects and cautions: ${esc(t.risks)}</p><a href="${esc(t.url)}" target="_blank" rel="noopener">Medicine information and risks</a>`).join('')}${guideCitation(c.source)}`;return `<p class="reply-label">About ${esc(names[c.id])}</p><p>${esc(intent==='simple'?c.plain:intent==='next'?c.diagnosis:intent==='symptoms'?'Symptoms described in the source include '+c.symptoms.join(', ')+'. These can overlap with other conditions.':c.description)}</p>${intent==='overview'?`<p>${esc(c.plain)}</p>`:''}${guideCitation(c.source)}<p>We can look at how this is investigated, or prepare questions for your appointment.</p><a class="link" href="#condition/${c.id}">Read the full guide</a>`}
 if(/doctor|appointment|dismiss|heard|misdiagnos/i.test(q))return `<p>It can be difficult to explain everything in a short appointment. Start with the symptom affecting you most, when it began, and how it changes your day. Bring your medicine list and any previous test results.</p><p>You could ask: “What possibilities are still being considered? What would the next test tell us? When should I follow up if I still feel unwell?”</p>${guideCitation({name:'National Institutes of Health',url:'https://health.nih.gov/health-topics-a-z/prepare-for-appointment',credentials:'NIH patient guidance on preparing for a medical appointment.'})}`;
 const hits=educationalResults(q,{mode:'general',filters:false}).slice(0,3);if(!hits.length)return '<p>I don’t have enough relevant source information to explain that reliably. Could you name the main symptom or condition? For example, “knee pain,” “fatigue,” or “migraine.”</p><p>You can also try the full medical library.</p><a href="#library">Open the library</a>';
 const e=hits[0],p=e.excerpt.split(/\n\s*\n/).find(p=>p.length>60);return `<p>The closest topic I found is <b>${esc(e.name)}</b>. This is a reading match, not a conclusion about what you have.</p>${p?`<p>Here is how the publisher describes it:</p><blockquote>${esc(p)}</blockquote>`:'<p>This entry has a source link but no explanation I can reliably build on yet.</p>'}<p>I don’t yet have an authored explanation for this question. The full guide includes the available source information and its limits.</p><a href="#condition/${e.id}">Read ${esc(e.name)}</a>${e.sources.slice(0,1).map(directorySource).join('')}`;
}
consultant=function(){return `<div class="consult-layout"><div class="consult-heading"><span class="eyebrow">PROGNOS CONSULTANT</span><h1>Let’s make sense of it, together.</h1><p>You don’t need the right medical words. Start with what’s troubling you.</p></div><div class="consult-topline"><span>${useLive&&liveAvailable?'AI explanations with linked evidence':liveAvailable?'Source-guided explanations · AI available below':'Source-guided explanations · live AI not connected'}</span><button class="text-button" onclick="newConsultation()" ${consultBusy?'disabled':''}>New conversation</button></div>${liveAvailable?`<label class="live-consent"><input type="checkbox" ${useLive?'checked':''} onchange="useLive=this.checked;render()"> Use AI explanations. Your messages will be sent to OpenAI to prepare a response.</label>`:''}<section class="consult-conversation" aria-label="Conversation">${!chat.length?`<div class="consult-welcome"><h2>What would you like to understand?</h2><p>We can unpack a symptom, explain a medical term, or help you prepare for your next appointment.</p><div class="consult-starters">${['I have knee pain','Why does anxiety make me tired?','Help me prepare for my doctor visit'].map(q=>`<button onclick="ask('${q}')">${q}</button>`).join('')}</div></div>`:''}<div id="messages" aria-live="polite" aria-busy="${consultBusy}">${chat.map((m,i)=>`<article class="consult-message ${m.role}"><span class="message-author">${m.role==='user'?'You':'Prognos'}</span><div id="reply-${i}">${m.html}</div>${m.role==='assistant'?`<button class="text-button" onclick="listenReply(${i})">Listen to this explanation</button>`:''}</article>`).join('')}${consultBusy?'<p role="status">Preparing your explanation…</p>':''}</div>${chat.length&&!consultBusy?`<div class="consult-followups">${followupPrompts.map(q=>`<button class="chip" onclick="ask('${q}')">${q}</button>`).join('')}</div>`:''}</section><form class="consult-compose" onsubmit="event.preventDefault();ask(this.q.value)"><label for="consult-question">Your question</label><textarea id="consult-question" name="q" rows="2" maxlength="2000" required placeholder="Tell me what you’d like to understand…" oninput="consultDraft=this.value" ${consultBusy?'disabled':''}>${esc(consultDraft)}</textarea><div><span>Information to support your care, not a diagnosis.</span><button class="primary" ${consultBusy?'disabled':''}>Send question</button></div></form><p class="fine">Conversation stays in this tab until you reload or start over. <a href="#emergency">Need urgent help?</a></p></div>`};
function newConsultation(){consultEpoch++;chat=[];guideTopic=null;consultDraft='';consultBusy=false;if('speechSynthesis'in window)speechSynthesis.cancel();render()}
function listenReply(i){if(!('speechSynthesis'in window))return toast('Reading aloud is not available in this browser.');speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(document.getElementById('reply-'+i).innerText))}
function liveReply(data){if(!data||!Array.isArray(data.paragraphs)||!Array.isArray(data.sources))throw Error('Invalid response');return data.paragraphs.map(p=>`<p>${esc(p.text)} ${p.sourceIds.map(id=>{const s=data.sources.find(s=>s.id===id);if(!s)throw Error('Missing source');return `<a class="inline-citation" href="${esc(s.url)}" target="_blank" rel="noopener">[${esc(id)}]</a>`}).join(' ')}</p>`).join('')+`<details class="consult-sources"><summary>Sources & credibility</summary>${data.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">[${esc(s.id)}] ${esc(s.name)}</a><br>${esc(s.credentials)}</p>`).join('')}</details>${data.question?`<p class="consult-question">${esc(data.question)}</p>`:''}`}
ask=async function(q){q=q.trim();if(!q||consultBusy)return;const epoch=consultEpoch;chat.push({role:'user',html:esc(q),text:q});consultDraft='';consultBusy=true;render();let html;
 try{if(useLive&&liveAvailable&&!urgentQuestion(q)){const context=chat.filter(m=>m.role==='user').slice(-6).map(m=>m.text||'');const response=await fetch('/api/consultant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:context,topic:guideTopic}),signal:AbortSignal.timeout(30000)});if(!response.ok)throw Error('AI response unavailable');html=liveReply(await response.json())}else html=localConsult(q)}catch{html='<p>Live AI is unavailable right now. Here is the source-guided explanation instead.</p>'+localConsult(q)}
 if(epoch!==consultEpoch)return;chat.push({role:'assistant',html});consultBusy=false;render();document.getElementById('consult-question')?.focus();};
// Only probes capability; no health information is sent by this request.
fetch('/api/consultant',{headers:{Accept:'application/json'}}).then(r=>r.ok?r.json():null).then(d=>{liveAvailable=d?.available===true;if(location.hash==='#consultant')render()}).catch(()=>{});
const quietRender=render;
render=function(){quietRender();document.querySelectorAll('.brandmark').forEach(el=>{el.innerHTML='<svg viewBox="0 0 48 48" role="img" aria-label="Prognos"><rect x="2" y="2" width="44" height="44" rx="14" fill="currentColor"/><path d="M20 10h8v10h10v8H28v10h-8V28H10v-8h10z" fill="var(--paper)"/><path d="M9 25h8l3-7 6 14 4-7h9" fill="none" stroke="var(--green)" stroke-width="1.8" stroke-linejoin="round"/></svg>'});};
render();
